import{_ as t}from"./chunks/eye.BRl0ZGNz.js";import{_ as a,c as n,o,ag as r}from"./chunks/framework.DZ_cNctr.js";const i="/docs/screenshots/channels-overview.png",s="/docs/screenshots/channels-card.png",l="/docs/screenshots/channels-color-picker.png",c="/docs/screenshots/channels-contrast.png",d="/docs/screenshots/channels-gamma.png",h="/docs/screenshots/channels-rgb-mode.png",p="/docs/screenshots/channels-state-fl-normal.png",g="/docs/screenshots/channels-state-fl-bw.png",m="/docs/screenshots/channels-state-fl-inv.png",u="/docs/screenshots/channels-state-fl-bw-inv.png",b="/docs/screenshots/channels-state-bf-normal.png",f="/docs/screenshots/channels-state-bf-bw.png",v="/docs/screenshots/channels-state-bf-inv.png",y="/docs/screenshots/channels-state-bf-bw-inv.png",I=JSON.parse('{"title":"Channels","description":"Control multi-channel fluorescence display in OME-Zarr images. Pick channel colors, adjust contrast with auto-contrast or manual sliders, gamma correction, RGB linked mode, black-and-white and invert display modes.","frontmatter":{"title":"Channels","description":"Control multi-channel fluorescence display in OME-Zarr images. Pick channel colors, adjust contrast with auto-contrast or manual sliders, gamma correction, RGB linked mode, black-and-white and invert display modes."},"headers":[],"relativePath":"guides/channels.md","filePath":"guides/channels.md"}'),w={name:"guides/channels.md"};function x(k,e,T,_,q,B){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to &quot;Channels&quot;">​</a></h1><p>A <strong>channel</strong> is one fluorescence wavelength, one brightfield layer, or any other intensity stream captured during imaging. Most microscopy datasets have between two and twelve channels; the viewer blends them in real time on the GPU so you can pick which ones to see, in which colors, at which contrast.</p><p>This guide covers every control in the <strong>Channels panel</strong>: colors, contrast, gamma, auto-contrast, and the display toggles (RGB, BW, INV).</p><p><img src="'+i+'" alt="Channels tab open in the sidebar, showing two or three channels each with a name, color swatch, contrast slider, and the SETTINGS row with RGB / BW / INV toggles at the top" style="max-width:380px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><h2 id="the-channels-panel" tabindex="-1">The Channels panel <a class="header-anchor" href="#the-channels-panel" aria-label="Permalink to &quot;The Channels panel&quot;">​</a></h2><p>Each channel takes one card. Cards stack vertically in the order the channels are stored in the OME-Zarr metadata. That order typically matches the acquisition order.</p><p>Each card shows:</p><ul><li><img src="'+t+'" class="fn-icon" alt="visibility"> toggle: turn the channel on or off</li><li>Channel name, e.g. <code>DAPI</code>, <code>GFP</code>, <code>Cy5</code></li><li>Color swatch: click to open the <strong>ColorPicker</strong> popover (presets + hex + RGB + native OS picker)</li><li><strong>Contrast</strong> section: dual-range slider showing min/max intensity clip points</li><li><strong>Gamma</strong> section (collapsible): gamma curve slider for non-linear contrast shaping</li></ul><p><img src="'+s+'" alt="Single channel card expanded showing the name + color swatch + eye toggle on the top row, Contrast section with histogram + dual slider below, and Gamma section collapsed" style="max-width:420px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><h2 id="channel-colors" tabindex="-1">Channel colors <a class="header-anchor" href="#channel-colors" aria-label="Permalink to &quot;Channel colors&quot;">​</a></h2><p>Click the color swatch on a channel to open the picker. Two rows of presets curated for fluorescence microscopy:</p><ul><li><strong>Row 1 (bright saturated)</strong>: White, Red, Green, Blue, Yellow, Cyan, Magenta, Black</li><li><strong>Row 2 (microscopy-friendly)</strong>: Gray, Orange (mCherry), Olive, Sky blue (DAPI), Amber (YFP), Teal, Pink, Purple (DRAQ5 / far-red)</li></ul><p>The bottom row sits next to the top row column-by-column so you can pick either the &quot;mathematically pure&quot; hue or the &quot;nicer-for-composites&quot; variant without re-hunting.</p><p>Under Presets the popover also has <strong>Hex</strong> and <strong>RGB</strong> inputs synced bidirectionally, and a <strong>More colors…</strong> button that opens the OS-native picker (Chrome / Edge also get the eyedropper for sampling colors from the image itself).</p><p><img src="'+l+'" alt="ColorPicker popover open: 2×8 presets grid at top, hex + RGB inputs below, More colors… button at the bottom" style="max-width:320px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><div class="tip custom-block"><p class="custom-block-title">Colour matching across surfaces</p><p>The same preset palette drives channel colours, label solid mode, and annotation colours. Picking &quot;Green&quot; on a channel gets the same hex as picking &quot;Green&quot; on an annotation. If you later want a colour-blind-safe palette, every surface flips together.</p></div><h2 id="contrast-the-dual-slider" tabindex="-1">Contrast: the dual slider <a class="header-anchor" href="#contrast-the-dual-slider" aria-label="Permalink to &quot;Contrast: the dual slider&quot;">​</a></h2><p>The <strong>Contrast</strong> section is a dual-range slider over the channel&#39;s intensity histogram. The left handle sets the intensity that maps to black; the right handle sets the intensity that maps to the channel&#39;s color at full saturation. Everything below the left handle clips to black; everything above the right handle saturates.</p><p>Underneath the slider: two number labels at the ends showing the current min / max values, and three tiny action buttons that appear on hover or when the slider is expanded:</p><table tabindex="0"><thead><tr><th>Action</th><th>Effect</th></tr></thead><tbody><tr><td><strong>AUTO</strong></td><td>Compute percentile-based auto-contrast (2nd–98th percentile by default). Runs a fast histogram pass over the currently-loaded tile data and sets min/max to fit. One click per channel.</td></tr><tr><td><strong>FIT</strong></td><td>Set min/max to the exact data range (0th–100th percentile). Useful for 16-bit data where most pixels are near zero but you want to see the full range anyway.</td></tr><tr><td><strong>HIST</strong></td><td>Toggle the histogram visualisation. When on, the slider sits over a mini histogram of the channel&#39;s intensity distribution. Useful for deciding where to set the clip points.</td></tr></tbody></table><p><img src="'+c+'" alt="Contrast section expanded with histogram visible underneath the dual slider, AUTO / FIT / HIST buttons on the right, min/max labels below the slider" style="max-width:420px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><h3 id="typing-exact-values" tabindex="-1">Typing exact values <a class="header-anchor" href="#typing-exact-values" aria-label="Permalink to &quot;Typing exact values&quot;">​</a></h3><p>Click either of the min/max labels below the slider. They turn into number inputs. Type a value and press Enter. The slider snaps to the typed value. Useful when you want to match the contrast from a publication, a teammate&#39;s view, or a previous session.</p><h3 id="when-to-use-auto-vs-manual" tabindex="-1">When to use auto vs manual <a class="header-anchor" href="#when-to-use-auto-vs-manual" aria-label="Permalink to &quot;When to use auto vs manual&quot;">​</a></h3><ul><li><strong>Auto-contrast</strong> is the right default for most data. It clips extreme outliers and stretches the middle 96% across the full brightness range.</li><li><strong>Manual</strong> when you need to compare two images with the same range (e.g., before/after treatment), or when auto over-compresses signal in a specific area you care about.</li><li><strong>Fit</strong> rarely does what you want on 16-bit data. The full dynamic range usually has too many dim pixels for the signal to show. Still useful for 8-bit or already-normalised data.</li></ul><h2 id="gamma-non-linear-contrast" tabindex="-1">Gamma: non-linear contrast <a class="header-anchor" href="#gamma-non-linear-contrast" aria-label="Permalink to &quot;Gamma: non-linear contrast&quot;">​</a></h2><p>Gamma bends the intensity-to-brightness mapping so dim details come up (gamma &lt; 1) or bright details get compressed (gamma &gt; 1). The <strong>Gamma</strong> section is collapsed by default; click the chevron to expand it.</p><p>Range is 0.1–3.0; default 1.0 (linear mapping). Typical useful range: 0.5 for &quot;brighten dim detail&quot; to 1.5 for &quot;tone down bright regions&quot;.</p><p><img src="'+d+'" alt="Gamma section expanded with the slider and numeric value, showing gamma 0.7 as an example" style="max-width:420px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><div class="warning custom-block"><p class="custom-block-title">Gamma on quantitative data</p><p>Gamma distorts the intensity-to-brightness mapping. Fine for visual inspection, misleading for quantitative comparisons. If you&#39;re going to publish the image, note the gamma setting in the figure caption (or set it back to 1.0 before screenshotting).</p></div><h2 id="display-modes-rgb-bw-inv" tabindex="-1">Display modes: RGB, BW, INV <a class="header-anchor" href="#display-modes-rgb-bw-inv" aria-label="Permalink to &quot;Display modes: RGB, BW, INV&quot;">​</a></h2><p>The <strong>SETTINGS</strong> row at the top of the Channels panel has three toggles:</p><h3 id="rgb-linked-sliders" tabindex="-1">RGB: linked sliders <a class="header-anchor" href="#rgb-linked-sliders" aria-label="Permalink to &quot;RGB: linked sliders&quot;">​</a></h3><p>RGB gives a true-colour image one contrast slider instead of three. The channel colour pickers lock to red, green and blue.</p><p>It does not change how the image looks. The viewer recognises true-colour data on its own and shows it correctly from the moment you open it. RGB only controls whether you adjust the three channels together or separately, which is why the button appears on those images and nowhere else.</p><p><img src="'+h+'" alt="RGB SETTINGS active, single linked contrast slider, channels 0-2 locked to red/green/blue" style="max-width:380px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><p>Use RGB for:</p><ul><li>True-color images (brightfield RGB captures, histology with R/G/B)</li><li>Linked adjustment when your three channels share a meaningful intensity range</li></ul><p>Turn RGB off to get back per-channel controls.</p><h3 id="bw-black-and-white-mode" tabindex="-1">BW: black-and-white mode <a class="header-anchor" href="#bw-black-and-white-mode" aria-label="Permalink to &quot;BW: black-and-white mode&quot;">​</a></h3><p>Force every visible channel to grayscale, ignoring their colors. Each channel still has its own contrast slider. BW just swaps the final blend to grayscale intensity.</p><p>Use BW for:</p><ul><li>Single-channel inspection when you want maximum perceptual detail (human eyes resolve intensity better than color)</li><li>Comparing channels side-by-side without color biasing the interpretation</li></ul><h3 id="inv-invert" tabindex="-1">INV: invert <a class="header-anchor" href="#inv-invert" aria-label="Permalink to &quot;INV: invert&quot;">​</a></h3><p>INV puts the image on a white background.</p><p>What you get depends on the data.</p><p><strong>Fluorescence keeps its colours.</strong> A channel set to blue stays blue and draws on white instead of black. Where two channels overlap, their colours mix darker, the way overlaid inks do.</p><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin:1rem 0;"><figure style="margin:0;"><img src="'+p+'" alt="neither" style="width:100%;border:1px solid var(--vp-c-divider);border-radius:6px;"><figcaption style="font-size:.8em;color:var(--vp-c-text-2);text-align:center;padding-top:4px;">neither</figcaption></figure><figure style="margin:0;"><img src="'+g+'" alt="BW" style="width:100%;border:1px solid var(--vp-c-divider);border-radius:6px;"><figcaption style="font-size:.8em;color:var(--vp-c-text-2);text-align:center;padding-top:4px;">BW</figcaption></figure><figure style="margin:0;"><img src="'+m+'" alt="INV" style="width:100%;border:1px solid var(--vp-c-divider);border-radius:6px;"><figcaption style="font-size:.8em;color:var(--vp-c-text-2);text-align:center;padding-top:4px;">INV</figcaption></figure><figure style="margin:0;"><img src="'+u+'" alt="BW + INV" style="width:100%;border:1px solid var(--vp-c-divider);border-radius:6px;"><figcaption style="font-size:.8em;color:var(--vp-c-text-2);text-align:center;padding-top:4px;">BW + INV</figcaption></figure></div><p><strong>Brightfield becomes a negative.</strong> An H&amp;E slide is dark stain on a bright background, so inverting it turns the tissue bright and the background dark. Stained regions then read the way fluorescent signal does.</p><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin:1rem 0;"><figure style="margin:0;"><img src="'+b+'" alt="neither" style="width:100%;border:1px solid var(--vp-c-divider);border-radius:6px;"><figcaption style="font-size:.8em;color:var(--vp-c-text-2);text-align:center;padding-top:4px;">neither</figcaption></figure><figure style="margin:0;"><img src="'+f+'" alt="BW" style="width:100%;border:1px solid var(--vp-c-divider);border-radius:6px;"><figcaption style="font-size:.8em;color:var(--vp-c-text-2);text-align:center;padding-top:4px;">BW</figcaption></figure><figure style="margin:0;"><img src="'+v+'" alt="INV" style="width:100%;border:1px solid var(--vp-c-divider);border-radius:6px;"><figcaption style="font-size:.8em;color:var(--vp-c-text-2);text-align:center;padding-top:4px;">INV</figcaption></figure><figure style="margin:0;"><img src="'+y+'" alt="BW + INV" style="width:100%;border:1px solid var(--vp-c-divider);border-radius:6px;"><figcaption style="font-size:.8em;color:var(--vp-c-text-2);text-align:center;padding-top:4px;">BW + INV</figcaption></figure></div><p>Use INV for:</p><ul><li>Figures headed for print, where a black background wastes ink and reads poorly</li><li>Journals and slide decks that expect dark objects on white</li><li>Reading an H&amp;E slide next to fluorescence without switching mental gears</li></ul><p>BW and INV work independently, so you get four combinations. BW + INV gives the classic dark cells on white.</p><h2 id="auto-contrast-details" tabindex="-1">Auto-contrast details <a class="header-anchor" href="#auto-contrast-details" aria-label="Permalink to &quot;Auto-contrast details&quot;">​</a></h2><p>Clicking <strong>AUTO</strong> on a channel runs percentile-based auto-contrast. The math:</p><ol><li>Sample the channel&#39;s currently-loaded tile data (whatever&#39;s visible at the current zoom).</li><li>Compute the 2nd and 98th percentiles.</li><li>Set the contrast min to the 2nd percentile and max to the 98th.</li></ol><p>The viewer keeps a cache so repeated AUTO clicks on the same zoom don&#39;t recompute. Moving to a new region and re-clicking AUTO recomputes for the new visible data.</p><p>A <strong>single-click all channels</strong> shortcut lives in the toolbar. Look for the &quot;Auto&quot; icon on the Channels panel header; it bumps every channel with one press.</p><h2 id="persistence" tabindex="-1">Persistence <a class="header-anchor" href="#persistence" aria-label="Permalink to &quot;Persistence&quot;">​</a></h2><p>Colors, min/max, gamma, visibility, and the RGB/BW/INV toggles all persist in two places:</p><ul><li>The <strong>URL query string</strong> (<code>?channels=0:on:00FF00:12:234,1:on:FF0000:50:890...</code>) for reviewer handoff via link.</li><li><strong>IndexedDB</strong> in your browser, keyed by image URL, so re-opening the same image without a URL state still restores your last configuration.</li></ul><p>The URL form is compact and human-readable; you can edit it by hand if needed (for batch image opens with pre-set channels, for example).</p><h2 id="keyboard" tabindex="-1">Keyboard <a class="header-anchor" href="#keyboard" aria-label="Permalink to &quot;Keyboard&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>1</code>–<code>9</code></td><td>Toggle channels 1–9 on / off</td></tr><tr><td><code>0</code></td><td>Toggle channel 10 (if present)</td></tr><tr><td><code>A</code></td><td>Auto-contrast all visible channels</td></tr></tbody></table><h2 id="image-credits" tabindex="-1">Image credits <a class="header-anchor" href="#image-credits" aria-label="Permalink to &quot;Image credits&quot;">​</a></h2><p>The screenshots on this page use a whole-slide H&amp;E section, a high-content screen and a plate from public collections. See <a href="./../sample-data.html">Sample Data and Credits</a>.</p><h2 id="related-guides" tabindex="-1">Related guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to &quot;Related guides&quot;">​</a></h2><ul><li><a href="./labels.html">Labels Guide</a>: segmentation overlays use channel colours for consistency</li><li><a href="./analytics-phenotyping.html">Analytics &amp; Phenotyping</a>: per-object coloring sits on top of label + channel rendering</li><li><a href="./sharing.html">Sharing Views</a>: channel state is in the URL; sharing a view sends the exact contrast + colors</li></ul>',68)])])}const P=a(w,[["render",x]]);export{I as __pageData,P as default};
